insert into public.pokedex_species (id, slug, ko_name, en_name, ko_form_name, en_form_name, form_of, ko_genus, en_genus, generation, category, type1, type2, hp, attack, defense, special_attack, special_defense, speed, height, weight, growth_rate, capture_rate, hatch_counter, gender_rate, evolves_from_id, evolution_method, sprites) values
  (10398, 'growlithe-hisui', '가디', 'Growlithe', '히스이의 모습', 'Hisuian Form', 58, '강아지포켓몬', 'Puppy Pokémon', 1, null,
insert into public.pokedex_kinds (id, ko_name, en_name) values
  ('hisui', '히스이도감', 'Hisui Pokédex')
insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 58, 10398, false, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
  ('national', 59, 10399, false, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
  ('national', 100, 10400, false, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
  ('national', 101, 10401, false, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
  ('national', 157, 10402, false, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('national', 211, 10403, false, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('national', 215, 10404, false, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
  ('national', 483, 10414, false, '시간을 조종하는 힘을 가지고 있다. 신오지방에서는 신이라고 불리며 신화에 등장한다.', 'This Pokémon is revered as a deity in Hisuian legend. The birth of Dialga was what caused the vast river of time to begin flowing in our world.'),
  ('national', 484, 10415, false, '공간을 뒤틀리게 하는 능력을 가졌으며 신오지방의 신화에서는 신으로 묘사되고 있다.', 'This Pokémon is feared as a deity in Hisuian legend. The birth of Palkia was what caused the walls of our world to disappear, creating a sky that spans for infinity.'),
  ('national', 503, 10405, false, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('national', 549, 10406, false, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('national', 550, 10416, false, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Though it differs from other Basculin in several respects, including demeanor—this one is gentle—I have categorized it as a regional form given the vast array of shared qualities.'),
  ('national', 570, 10407, false, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
  ('national', 571, 10408, false, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
  ('national', 628, 10409, false, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
  ('national', 705, 10410, false, '등의 돌기 안에 작은 뇌가 있다. 먹이에 대한 생각과 적으로부터 도망치는 생각만 한다.', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
  ('national', 706, 10411, false, '긴 뿔을 기세 좋게 늘여서 공격한다. 위력은 헤비급 복서 펀치의 100배다.', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
  ('national', 713, 10412, false, '낮 동안의 활동으로 몸의 균열이 깊어지지만 하룻밤 사이에 균열이 없는 몸으로 돌아간다.', 'The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.'),
  ('national', 724, 10413, false, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('national', 899, 899, true, null, 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.'),
  ('national', 900, 900, true, null, 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.'),
  ('national', 901, 901, true, null, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.'),
  ('national', 902, 902, true, null, 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.'),
  ('national', 902, 10417, false, null, 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.'),
  ('national', 903, 903, true, null, 'Because of Sneasler''s virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.'),
  ('national', 904, 904, true, null, 'Its lancelike spikes and savage temperament have earned it the nickname ”sea fiend.” It slurps up poison to nourish itself.'),
  ('national', 905, 905, true, null, 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.'),
  ('national', 905, 10418, false, null, 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.'),
  ('kanto', 58, 10398, false, '사람을 잘 따르는 성격이지만 영역에 들어온 상대에게는 격렬하게 짖는다.', 'A Pokémon with a friendly nature. However, it will bark fiercely at anything invading its territory.'),
  ('kanto', 59, 10399, false, '동양의 전설의 포켓몬. 경쾌하게 달리는 그 모습에 반하는 자도 많다.', 'A legendary Pokémon in the East. Many people are charmed by the grace and beauty of its running.'),
  ('kanto', 100, 10400, false, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'It is said to camouflage itself as a Poké Ball. It will self-destruct with very little stimulus.'),
  ('kanto', 101, 10401, false, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'Stores electrical energy inside its body. Even the slightest shock could trigger a huge explosion.'),
  ('johto', 6, 10402, false, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'If its rage peaks, it becomes so hot that anything that touches it will instantly go up in flames.'),
  ('johto', 120, 10400, false, '몬스터볼과 닮은 것은 보호색으로 위장하기 위해서라고 전해지나 의외로 쉽게 자폭한다.', 'It rolls to move. If the ground is uneven, a sudden jolt from hitting a bump can cause it to explode.'),
  ('johto', 121, 10401, false, '조금이라도 충격을 주면 체내에 있는 전기 에너지가 넘쳐서 폭발해버린다.', 'It is dangerous. If it has too much electricity and has nothing to do, it amuses itself by exploding.'),
  ('johto', 127, 10398, false, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'It has a brave and trustworthy nature. It fearlessly stands up to bigger and stronger foes.'),
  ('johto', 128, 10399, false, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'This legendary Chinese Pokémon is considered magnificent. Many people are enchanted by its grand mane.'),
  ('johto', 161, 10403, false, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'To fire its poison spikes, it must inflate its body by drinking over 2.6 gallons of water all at once.'),
  ('johto', 213, 10404, false, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'Its paws conceal sharp claws. If attacked, it suddenly extends the claws and startles its enemy.'),
  ('hoenn', 84, 10400, false, '몬스터볼을 만드는 회사에서 처음 발견됐다는 점과 생김새가 비슷한 점의 관련성은 아직도 수수께끼다.', 'Voltorb was first sighted at a company that manufactures Poké Balls. The link between that sighting and the fact that this Pokémon looks very similar to a Poké Ball remains a mystery.'),
  ('hoenn', 85, 10401, false, '공기 중의 전기 에너지를 먹는다. 번개가 치는 날에는 전기를 너무 먹은 붐볼이 이곳저곳에서 대폭발한다.', 'Electrode eats electricity in the atmosphere. On days when lightning strikes, you can see this Pokémon exploding all over the place from eating too much electricity.'),
  ('sinnoh', 144, 10404, false, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'A smart and sneaky Pokémon. A pair may work together to steal eggs by having one lure the parents away.'),
  ('sinnoh', 149, 10414, false, '시간을 조종하는 힘을 가지고 있다. 신오지방에서는 신이라고 불리며 신화에 등장한다.', 'A legendary Pokémon of Sinnoh. It is said that time flows when DIALGA’s heart beats.'),
  ('sinnoh', 150, 10415, false, '공간을 뒤틀리게 하는 능력을 가졌으며 신오지방의 신화에서는 신으로 묘사되고 있다.', 'A legendary Pokémon of Sinnoh. It is said that space becomes more stable with PALKIA’s every breath.'),
  ('unova', 9, 10405, false, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'In the time it takes a foe to blink, it can draw and sheathe the seamitars attached to its front legs.'),
  ('unova', 51, 10398, false, '충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.', 'Extremely loyal to its Trainer, it will bark at those who approach the Trainer unexpectedly and run them out of town.'),
  ('unova', 52, 10399, false, '옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.', 'The sight of it running over 6,200 miles in a single day and night has captivated many people.'),
  ('unova', 85, 10406, false, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'The fragrance of the garland on its head has a relaxing effect, but taking care of it is very difficult.'),
  ('unova', 104, 10416, false, '옛날에는 식탁에 올랐다. 적색근 배쓰나이의 살코기는 기름이 많아 젊은 층이 좋아한다.', 'Red- and blue-striped Basculin are very violent and always fighting. They are also remarkably tasty.'),
  ('unova', 110, 10409, false, '혈기왕성하고 거칠어서 가라르의 배달부 자리는 아머까오에게 뺏겼다.', 'For the sake of its friends, this brave warrior of the sky will not stop battling, even if injured.'),
  ('unova', 151, 10407, false, '먹이를 찾아 사람으로 둔갑하여 마을에 나타나기도 한다. 주로 아이로 둔갑한다.', 'It changes so it looks just like its foe, tricks it, and then uses that opportunity to flee.'),
  ('unova', 152, 10408, false, '고독한 트레이너는 조로아크에게 환상을 보여주도록 명령하여 혼자만의 외로움을 달랜다.', 'Stories say those who tried to catch Zoroark were trapped in an illusion and punished.'),
  ('unova', 252, 10404, false, '교활하고 사나운 성질을 가졌다. 부모가 없는 틈에 둥지로 침입해서 알을 훔친다.', 'A smart and sneaky Pokémon, it makes its opponents flinch by suddenly showing the claws hidden in its paws.'),
  ('kalos', 188, 10403, false, '전신의 독침을 날리기 위해 10리터의 물을 단번에 마시고 몸을 부풀린다.', 'To fire its poison spikes, it must inflate its body by drinking over 2.6 gallons of water all at once.'),
  ('kalos', 323, 10410, false, '무엇이든 녹여버리는 점액을 분비해 적을 격퇴한다. 눈은 퇴화하여 보이지 않는다.', 'It drives away opponents by excreting a sticky liquid that can dissolve anything. Its eyes devolved, so it can’t see anything.'),
  ('kalos', 324, 10411, false, '사람을 잘 따르는 드래곤포켓몬이다. 좋아하는 트레이너에게 달려들어 미끈미끈한 점액투성이로 만들어 버린다.', 'This very friendly Dragon-type Pokémon will hug its beloved Trainer, leaving that Trainer covered in sticky slime.'),
  ('kalos', 363, 10416, false, '아주 난폭하고 항상 빨강과 파랑의 배쓰나이는 다투고 있다. 먹으면 의외로 맛있다고 한다.', 'Red- and blue-striped Basculin are very violent and always fighting. They are also remarkably tasty.'),
  ('kalos', 375, 10400, false, '몬스터볼이 팔리기 시작했을 때와 같은 시기에 발견되었다. 뭔가 관계가 있다고 전해진다.', 'It was discovered when Poké Balls were introduced. It is said that there is some connection.'),
  ('kalos', 376, 10401, false, '작은 자극에도 반응해서 폭발한다. 폭탄볼이라 불리며 두려움의 대상이 되고 있다.', 'It explodes in response to even minor stimuli. It is feared, with the nickname of “The Bomb Ball.”'),
  ('kalos', 383, 10412, false, '얼어붙은 몸은 강철처럼 단단하다. 앞을 가로막는 것을 커다란 몸으로 파괴하며 이동한다.', 'Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.'),
  ('kalos', 394, 10404, false, '거처에서 알을 가로채어 먹어 버린다. 날카로운 갈고리 손톱이 상대의 급소를 베어 가른다.', 'It feeds on eggs stolen from nests. Its sharply hooked claws rip vulnerable spots on prey.'),
  ('kalos', 427, 10407, false, '상대와 똑 닮게 둔갑한 것처럼 보이게 하여 속이거나 놀라게 해서 그 틈에 도망가는 일이 많다.', 'It changes so it looks just like its foe, tricks it, and then uses that opportunity to flee.'),
  ('kalos', 428, 10408, false, '한 번에 많은 사람을 속이는 힘을 가졌다. 환영의 경치를 보여줘 거처를 지킨다.', 'Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.'),
  ('alola', 3, 10413, false, '살깃을 시위에 메겨서 상대에게 날린다. 반드시 명중시켜야 할 때는 머리의 시위를 당겨 집중한다.', 'It nocks its arrow quills and shoots them at opponents. When it simply can’t afford to miss, it tugs the vine on its head to improve its focus.'),
  ('alola', 28, 10407, false, '겁이 많은 포켓몬으로 동료와 있을 때 말고는 거의 다른 누군가로 둔갑하고 있다.', 'This Pokémon has a cowardly disposition, so when it’s not around friends, it basically always stays transformed as something else.'),
  ('alola', 29, 10408, false, '둔갑술이 가능할 뿐만 아니라 수백 명의 사람에게 환상을 보여줄 수 있는 힘을 가졌다.', 'It doesn’t just transform itself—it also has the power to make hundreds of people see its illusions.'),
  ('alola', 64, 10398, false, '익숙해지면 사람을 잘 따르지만, 야생에서는 암멍이와 영역을 두고 격렬히 다툰다.', 'While it’s quite friendly toward humans once it’s grown used to them, in the wild it must be quite fierce to defend its territory from Rockruff.'),
  ('alola', 65, 10399, false, '아주 먼 옛날 어느 장수와 함께 싸워 나라를 다스렸다고 하는 전설이 남아 있다.', 'Legends tell of its fighting alongside a general and conquering a whole country.'),
  ('alola', 90, 10409, false, '안면에 상처가 많을수록 용감하다고 평가받고 뒤에 상처가 많으면 무리에서 무시당한다.', 'The more scars it has on its front, the more heroic it’s considered to be. Those with many scars on their back are mocked by the flock.'),
  ('alola', 104, 10406, false, '자란 흙의 성분에 따라 꽃향기는 조금씩 다르다. 냄새를 맡으면 마음이 치유되고 평온해진다.', 'The fragrance of its flower differs slightly depending on the soil where it grew up. Sniffing the aroma calms your heart and mind.'),
  ('alola', 188, 10416, false, '난폭하고 사나운 포켓몬. 빨강과 파랑의 배쓰나이는 영역을 두고 언제나 싸운다.', 'Savage, violent Pokémon, red and blue Basculin are always fighting each other over territory.'),
  ('alola', 218, 10410, false, '느릿느릿 기어서 이동한다. 나선의 돌기는 뇌와 내장으로 꽉 차 있다.', 'It crawls along sluggishly. The swirly protrusion on its back is filled with its brain and other organs.'),
  ('alola', 219, 10411, false, '매우 사람을 잘 따른다. 친밀해지면 끈적끈적한 점액투성이인 몸으로 끌어안으려 하지만 참아야 한다.', 'It’s very friendly toward people. If you grow close to it, Goodra will hug you with its sticky, slime-covered body. Don’t get mad.'),
  ('alola', 326, 10404, false, '팀플레이로 새포켓몬의 둥지에서 알을 훔쳐 내지만, 누가 먹을까로 싸움이 난다.', 'They will cooperate to steal eggs from the nests of bird Pokémon, but fights break out to determine which one gets to eat the eggs.'),
  ('galar', 70, 10398, false, '자신보다 강하고 큰 상대라도 겁 없이 맞서는 용감하고 믿음직스런 성격이다.', 'It has a brave and trustworthy nature. It fearlessly stands up to bigger and stronger foes.'),
  ('galar', 71, 10399, false, '하루 만에 10000km의 거리를 달리는 모습은 많은 사람을 매료시켜 왔다.', 'The sight of it running over 6,200 miles in a single day and night has captivated many people.'),
  ('galar', 154, 10416, false, '힘이 세기 때문에 낚시꾼들에게 인기가 많다. 무단으로 연못에 놓아줘서 점점 개체 수가 늘어나고 있다.', 'Anglers love the fight this Pokémon puts up on the hook. And there are always more to catch— many people release them into lakes illicitly.'),
  ('galar', 282, 10409, false, '용맹하고 긍지 높은 포켓몬. 그 용감한 모습 때문에 엠블럼의 모티브로 인기가 많다.', 'Known for its bravery and pride, this majestic Pokémon is often seen as a motif for various kinds of emblems.'),
  ('galar', 292, 10404, false, '예리한 손톱을 손가락 안에 감추고 있다. 갑자기 뻗어서 습격해온 상대를 풀죽게 만든다.', 'Its paws conceal sharp claws. If attacked, it suddenly extends the claws and startles its enemy.'),
  ('galar', 304, 10403, false, '상대가 크면 클수록 몸이 터지기 직전까지 물을 들이마셔서 몸을 부풀린다.', 'When faced with a larger opponent, it swallows as much water as it can to match the opponent’s size.'),
  ('galar', 359, 10412, false, '여러 마리의 꽁어름을 등에 태우고 고위도의 차가운 바다를 빙산 속에 섞여 헤엄친다.', 'At high latitudes, this Pokémon can be found with clusters of Bergmite on its back as it swims among the icebergs.'),
  ('galar', 390, 10410, false, '무엇이든 녹여버리는 점액으로 몸을 보호하기 때문에 약하지만 먹히지 않고 살아남을 수 있었다.', 'Although this Pokémon isn’t very strong, its body is coated in a caustic slime that can melt through anything, so predators steer clear of it.'),
  ('galar', 391, 10411, false, '트레이너의 지시를 이해하지 못하고 어리둥절해하는 경우가 가끔 있으며 그 모습이 귀여워서 인기가 많다.', 'Sometimes it misunderstands instructions and appears dazed or bewildered. Many Trainers don’t mind, finding this behavior to be adorable.'),
  ('galar', 445, 10407, false, '무언가로 둔갑하는 능력을 익힌 것은 겁이 많은 성질의 영향인 듯하다.', 'Zorua is a timid Pokémon. This disposition seems to be what led to the development of Zorua’s ability to take on the forms of other creatures.'),
  ('galar', 446, 10408, false, '동료애가 깊은 포켓몬이다. 무서운 환상을 보게 만들어서 거처나 무리를 지킨다.', 'This Pokémon cares deeply about others of its kind, and it will conjure terrifying illusions to keep its den and pack safe.'),
  ('galar', 504, 10406, false, '일류 원예가라 하더라도 머리의 꽃을 피우는 일은 매우 어렵다고 전해진다.', 'It’s believed that even first-rate gardeners have a hard time getting the flower on a Lilligant’s head to bloom.'),
  ('hisui', 1, 722, true, '낮 동안에는 광합성으로 힘을 비축하고 밤이 되면 소리 없이 날며 먹이를 찾는다.', 'Flies noiselessly on delicate wings. It has mastered the art of deftly launching dagger-sharp feathers from those same wings.'),
  ('hisui', 2, 723, true, '날개 손질을 게을리하지 않는다. 몸가짐을 정돈하는 이유뿐만 아니라 칼날깃의 날을 유지하기 위해서다.', 'Regularly basks in sunlight to gather power—presumably due to the frigid climate. Nonetheless, the edges of the blade quills set into its wings are keen as ever.'),
  ('hisui', 3, 724, true, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('hisui', 3, 10413, false, '0.1초 만에 화살깃을 날개에 달린 시위에 메겨 발사한다. 상대가 알아차리기 전에 급소를 꿰뚫어버린다.', 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
  ('hisui', 4, 155, true, '등에서 불꽃을 내뿜어 몸을 지킨다. 화났을 때의 불꽃은 기운차지만 지쳤을 때는 불완전연소한다.', 'Hails from the Johto region. Though usually curled into a ball due to its timid disposition, it harbors tremendous firepower.'),
  ('hisui', 5, 156, true, '불꽃의 기세와 열풍으로 위협한다. 재빠른 몸동작으로 상대의 공격을 피하면서 동시에 불꽃으로 태운다.', 'This creature''s fur is most mysterious—it is wholly impervious to the burning touch of flame. Should Quilava turn its back to you, take heed! Such a posture indicates a forthcoming attack.'),
  ('hisui', 6, 157, true, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('hisui', 6, 10402, false, '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
  ('hisui', 7, 501, true, '배에 있는 가리비칼로 싸운다. 공격을 막고 그 즉시 베어 반격한다.', 'This Pokémon from the Unova region uses the shell on its belly as a weapon to cut down its foes. Thus, I''ve conferred upon this shell the name ”scalchop”.'),
  ('hisui', 8, 502, true, '혹독한 수행 끝에 쌍검자비마다 다른 형태의 가리비칼 다루는 기술을 습득한다.', 'Its exquisite double-scalchop technique is likely the result of daily training, and it can send even masters of the blade fleeing in defeat.'),
  ('hisui', 9, 503, true, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('hisui', 9, 10405, false, '갑옷에 내장된 검으로 한칼에 상대를 제압한다. 눈빛만으로 상대를 침묵시킨다.', 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
  ('hisui', 10, 399, true, '항상 큰 나무나 돌을 갉아서 튼튼한 앞니를 갈아내고 있다. 물가에 둥지를 만들어 산다.', 'Bidoof has an unsophisticated face and is rarely flustered by anything. There have been incidents involving Bidoof sauntering into villages and gnawing on the houses without a single care.'),
  ('hisui', 11, 400, true, '강을 나무줄기나 진흙의 댐으로 막아서 거처를 만든다. 부지런한 일꾼으로 알려져 있다.', 'Bibarel fur repels water and is also a fantastic material for heat retention. These Pokémon create dams on rivers to live in.'),
  ('hisui', 12, 396, true, '벌레 포켓몬을 노리고 산과 들을 많은 무리로 날아다닌다. 울음소리가 무척 시끄럽다.', 'They live in the fields and mountains, gathering in large flocks. Their cries are quite obnoxious. Though small, their wings are strong—a strike from them leaves pain that persists for a week.'),
  ('hisui', 13, 397, true, '숲이나 초원에 서식한다. 그룹이 마주치면 영역을 건 분쟁이 시작된다.', 'They form remarkably large flocks and are constantly fighting amongst themselves. I suspect that those with magnificent plumes on their heads are the strong ones.'),
  ('hisui', 14, 398, true, '찌르호크가 되면 무리에서 떨어져 혼자서 살아간다. 강인한 날개를 가지고 있다.', 'It has left the flock, having gained strength enough to survive on its own. The astounding force with which Staraptor flies through the air allows it to carry away large, burly targets.'),
  ('hisui', 15, 403, true, '털이 전기로 빛난다. 밝게 빛나는 꼬리 끝을 흔들어 동료에게 신호를 보낸다.', 'Shakes its body to generate electricity. Its stature belies its aggression—one must be patient to tame this Pokémon.'),
  ('hisui', 16, 404, true, '적을 만나면 100만 볼트의 위력을 가진 발톱을 드러내어 싸움에 대비한다.', 'Proudly uses its electrified claws as weapons. It seems to be a gracious Pokémon, evenly sharing the spoils of the hunt with others of its kind.'),
  ('hisui', 17, 405, true, '투시는 전기 에너지를 매우 많이 소모하기 때문에 오랜 시간 수면을 취해서 에너지를 비축한다.', 'They form packs, each having one male as leader. Legends say that when Luxray''s two eyes shimmer with gold, the Pokémon can see through anything.'),
  ('hisui', 18, 265, true, '먹이로 삼으려고 다가온 스왈로에게 엉덩이의 가시를 들이밀고 저항한다. 배어 나온 독으로 상대를 약하게 만든다.', 'Likes sap and is abundant in the wild. Why it evolves into various different forms is unknown. One cannot tell from a Wurmple''s appearance which form it will take when it evolves.'),
  ('hisui', 19, 266, true, '진화할 때까지 아무것도 먹지 않고 참는 것으로 여겨져 왔으나 아무래도 실에 맺힌 빗방울로 갈증을 푸는 것 같다.', 'Wraps itself in thin strings of silk while it stores energy for evolution. It can''t extend its limbs and its movement is slow, but its eyes keep a sharp lookout—Silcoon is always on guard.'),
  ('hisui', 20, 267, true, '둥글게 말린 바늘같이 생긴 긴 입은 꽃가루를 모을 때 매우 편리하다. 봄바람을 타고 꽃가루를 모으러 돌아다닌다.', 'A colorful and incredibly beautiful but also greedy Pokémon. In an effort to keep its favorite food all to itself, it will chase away Combee as they try to gather nectar.'),
  ('hisui', 21, 268, true, '움직이면 튼튼한 몸으로 진화할 수 없어서 아무리 괴롭혀도 가만히 있는다. 그때 느낀 아픔을 계속 잊지 않는다.', 'The silk coating its body is thin but sufficiently strong. Cascoon''s silk has a luster and texture superior to that of Silcoon''s, and clothes made using Cascoon silk are regarded as top-notch.'),
  ('hisui', 22, 269, true, '날갯짓하면 미세한 가루가 날린다. 들이마시면 프로레슬러도 잠드는 맹독이다. 더듬이의 레이더로 먹이를 찾는다.', 'Tends to be drawn to bonfires on dark nights. Difficult to chase away from settlements because of the way it scatters highly toxic scales.'),
  ('hisui', 23, 77, true, '포니타에게 인정받으면 타오르는 갈기를 만져도 뜨거움을 느끼지 않게 된다.', 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
  ('hisui', 23, 10321, false, '포니타에게 인정받으면 타오르는 갈기를 만져도 뜨거움을 느끼지 않게 된다.', 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
  ('hisui', 24, 78, true, '가장 발이 빠른 날쌩마가 리더가 되어 무리가 갈 장소나 달리는 속도를 정한다.', 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
  ('hisui', 24, 10322, false, '가장 발이 빠른 날쌩마가 리더가 되어 무리가 갈 장소나 달리는 속도를 정한다.', 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
  ('hisui', 25, 133, true, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Harbors the potential to evolve into manifold forms. Within Eevee lies the key to the mysteries of Pokémon evolution—I''m certain of it.'),
  ('hisui', 25, 10374, false, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Harbors the potential to evolve into manifold forms. Within Eevee lies the key to the mysteries of Pokémon evolution—I''m certain of it.'),
  ('hisui', 26, 134, true, '몸의 세포 구조가 물 분자와 닮았다. 물에 녹으면 보이지 않는다.', 'Tests show that its cells closely resemble water molecules, which perhaps explains its ability to conceal its form while submerged. I believe the origins of mermaid folklore lie with this Pokémon.'),
  ('hisui', 27, 135, true, '공기 중의 마이너스 이온을 빨아들여 약 10000볼트의 전기를 내뱉을 수 있다.', 'Bristles its fur into sharp, needlelike points when enraged. One can hear electricity crackle in its breath when it exhales.'),
  ('hisui', 28, 136, true, '들이마신 공기 중 일부는 체내의 불꽃 주머니로 보내져 1700도의 불꽃이 된다.', 'Flames burn within a saclike organ inside this Pokémon. When Flareon inhales, these flames grow in intensity, reaching a mighty 3,000 degrees Fahrenheit.'),
  ('hisui', 29, 196, true, '이마의 구슬에서 사이코 파워를 방사해서 싸운다. 파워가 다하면 구슬의 색이 흐려진다.', 'Wields an arcane power with which it can predict the weather and even people''s thoughts. When bathed in sunshine, the scarlet orb on its brow glows and builds energy.'),
  ('hisui', 30, 197, true, '보름달이 뜬 밤이나 흥분했을 때 전신의 고리 무늬가 노랗게 빛난다.', 'It is most active in the wee hours of the night, when moonlight bathes the land. Its large eyes can pierce the darkness and perceive prey with absolute clarity.'),
  ('hisui', 31, 470, true, '꼬리는 날카로운 칼날 같다. 큰 나무도 두 동강 내는 탁월한 예리함을 자랑한다.', 'Cells similar to those of plants have been found in its fur. Its hard tail can fell a large tree with one stroke, and the tail''s sharpness exceeds even that of a sword crafted by a master.'),
  ('hisui', 32, 471, true, '글레이시아가 발산하는 냉기는 가루눈을 만들어 내기 때문에 스키장에서 인기가 높다.', 'Glaceon is able to lower its body temperature very quickly. It freezes the atmosphere, creating diamond dust that glitters like gems while it flutters and dances around.'),
  ('hisui', 33, 700, true, '무서운 드래곤포켓몬을 아름다운 님피아가 퇴치하는 동화가 가라르지방에 남아 있다.', 'It emits a soothing aura from its ribbon-shaped organs. It wraps these appendages around quarrelers to instantly restore calm to the situation.'),
  ('hisui', 34, 41, true, '볕이 들지 않는 동굴에 산다. 아침이 되면 동료들끼리 모여 서로의 온기를 나누면서 잔다.', 'Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.'),
  ('hisui', 35, 42, true, '작은 다리로 능숙하게 걷는다. 자고 있는 먹이에게 살며시 다가가 이빨을 꽂아 피를 빨아먹는다.', 'It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.'),
  ('hisui', 36, 169, true, '4장의 날개를 자유자재로 움직이며 날갯짓한다. 좁은 동굴에서도 속도를 늦추지 않고 날아다닐 수 있다.', 'Its hind limbs have become another set of wings. Crobat expertly maneuvers its four wings to dart in exquisite fashion through even the most confined caves without losing any speed.'),
  ('hisui', 37, 425, true, '영혼들이 모여 탄생했다. 습기가 많은 계절에는 대량으로 나타나기도 한다.', 'Said to lure away young children and carry them off to the afterlife. Some whisper that Drifloon are formed of reincarnated human souls, but these rumors are as yet unconfirmed.'),
  ('hisui', 38, 426, true, '사람과 포켓몬을 붙잡아 그대로 어딘가로 운반한다. 행선지는 아무도 모른다.', 'It drifts along at dusk, perfectly silent. Its transient, melancholy aspect touches some people deeply—every so often, one will come upon a song or poem devoted to Drifblim.'),
  ('hisui', 39, 401, true, '더듬이가 서로 부딪히면 딩동딩동 실로폰 같은 음색을 연주한다.', 'When the trees take on new hues, more of these Pokémon appear. The tone they create by striking their antennae together resembles that of the marimba, an instrument of foreign lands.'),
  ('hisui', 40, 402, true, '감정을 멜로디로 나타낸다. 멜로디의 법칙성을 학자들이 연구하고 있다.', 'It uses its cutlass-like arms to produce sound, the melody of which varies from individual to individual. It is a worthwhile endeavor to seek out one''s favorite tunes.'),
  ('hisui', 41, 418, true, '목의 부낭을 부풀려 수면에서 얼굴을 내밀어 주변의 상황을 살피고 있다.', 'It moves freely in the water by spinning its forked tail for propulsion. The resemblance to the screw of a steamboat is coincidental.'),
  ('hisui', 42, 419, true, '수중의 먹이를 쫓아가는 사이에 부낭이 발달했다. 고무보트처럼 사람을 태운다.', 'Has a long, rather splendid flotation sac, which prevents Floatzel from drowning even in stormy seas. One might glimpse this species around fishing hamlets from time to time.'),
  ('hisui', 43, 412, true, '싸움으로 도롱이가 부서져 버리면 가까이 있는 재료로 도롱이를 바로 만들어 고친다.', 'If its cloak is even slightly damaged, Burmy will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.'),
  ('hisui', 43, 10034, false, '싸움으로 도롱이가 부서져 버리면 가까이 있는 재료로 도롱이를 바로 만들어 고친다.', 'If its cloak is even slightly damaged, Burmy will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.'),
  ('hisui', 43, 10035, false, '싸움으로 도롱이가 부서져 버리면 가까이 있는 재료로 도롱이를 바로 만들어 고친다.', 'If its cloak is even slightly damaged, Burmy will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.'),
  ('hisui', 44, 413, true, '도롱충이로부터 진화할 때 도롱이가 몸의 일부가 되었다. 일생 도롱이를 벗는 일은 없다.', 'When Burmy evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed.'),
  ('hisui', 44, 10036, false, '도롱충이로부터 진화할 때 도롱이가 몸의 일부가 되었다. 일생 도롱이를 벗는 일은 없다.', 'When Burmy evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed.'),
  ('hisui', 44, 10037, false, '도롱충이로부터 진화할 때 도롱이가 몸의 일부가 되었다. 일생 도롱이를 벗는 일은 없다.', 'When Burmy evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed.'),
  ('hisui', 45, 414, true, '한밤중에 활발하게 날아다니며 잠든 세꿀버리의 둥지에서 꿀을 훔쳐 달아난다.', 'Scatters steel-colored scales as it flaps its wings. Despite being observed feeding primarily on the nectar of flowers, Mothim is not often seen around flower gardens.'),
  ('hisui', 46, 74, true, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
  ('hisui', 46, 10211, false, '산길 등에 많이 서식한다. 실수로 밟으면 화를 내므로 주의가 필요하다.', 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
  ('hisui', 47, 75, true, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
  ('hisui', 47, 10212, false, '산길에서 자주 굴러다닌다. 가는 길에 무엇이 있든 전혀 신경 쓰지 않는다.', 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
  ('hisui', 48, 76, true, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
  ('hisui', 48, 10213, false, '탈피한 직후에는 전체가 하얗고 부드럽지만 금방 공기와 접촉해서 단단해진다.', 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
  ('hisui', 49, 234, true, '멋지게 생긴 뿔은 미술품으로 비싸게 팔리기 때문에 멸종 직전까지 남획됐었던 포켓몬이다.', 'Its strangely shaped antlers have the power to bewitch those who see them. Medicine made by grinding up the black orbs from fallen antlers is an effective treatment for insomnia.'),
  ('hisui', 50, 899, true, null, 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.'),
  ('hisui', 51, 446, true, '털 안에 먹이를 모은다. 신뢰하는 상대에게는 한 입 나눠주기도 한다.', 'Its robust stomach allows it to nonchalantly devour even rotted matter. It pays frequent visits to villages, seeking out food scraps intended for compost.'),
  ('hisui', 52, 143, true, '위장이 튼튼해서 곰팡이가 피거나 썩은 것을 먹어도 배탈이 나지 않는다.', 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
  ('hisui', 52, 10375, false, '위장이 튼튼해서 곰팡이가 피거나 썩은 것을 먹어도 배탈이 나지 않는다.', 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
  ('hisui', 53, 46, true, '구멍을 파서 나무뿌리로부터 영양을 섭취하지만 대부분은 등에 있는 버섯에게 빼앗긴다.', 'Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as Paras matures.'),
  ('hisui', 54, 47, true, '계속 진액을 빨아 먹혀서 이제는 벌레가 아니라 등에 있는 버섯이 생각하고 있는 듯하다.', 'Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of Parasect''s actions.'),
  ('hisui', 55, 172, true, '볼의 전기 주머니가 작아서 조금이라도 전기가 넘치게 되면 자기 자신이 감전되어 버린다.', 'Pichu stores electricity in the sacs on its cheeks but discharges it inadvertently when agitated or excited. Being yet immature, the Pokémon''s handling of electricity is rather inept.'),
  ('hisui', 55, 10065, false, '볼의 전기 주머니가 작아서 조금이라도 전기가 넘치게 되면 자기 자신이 감전되어 버린다.', 'Pichu stores electricity in the sacs on its cheeks but discharges it inadvertently when agitated or excited. Being yet immature, the Pokémon''s handling of electricity is rather inept.'),
  ('hisui', 56, 25, true, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10196, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10197, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10198, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10199, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10200, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10201, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10267, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10319, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 56, 10368, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('hisui', 57, 26, true, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('hisui', 57, 10202, false, '전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.', 'It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.'),
  ('hisui', 58, 63, true, '잠이 든 상태에서 순간이동이 가능하다. 깊이 잠들수록 먼 곳으로 이동한다고 한다.', 'Spends 18 hours of the day sleeping. Even while asleep, Abra can control its psychic powers—should danger approach, the Pokémon will simply teleport away.'),
  ('hisui', 59, 64, true, '염동력의 위력은 절대적이다. 진화에 대비하여 이마에 있는 별에 사이코 파워를 비축하고 있다.', 'There are rumors that a child with mystical powers became a Kadabra; however, this remains unverified. I suspect that the spoon Kadabra holds enhances its brain waves.'),
  ('hisui', 60, 65, true, '강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.', 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
  ('hisui', 60, 10137, false, '강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.', 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
  ('hisui', 61, 390, true, '배에서 만들어진 가스가 엉덩이에서 타오르고 있다. 몸 상태가 나쁘면 불꽃이 약해진다.', 'Full of vigor and always in high spirits. It was once known by the name ”Lantern-Tail” and feared as some kind of apparition.'),
  ('hisui', 62, 391, true, '천장이나 벽을 이용하여 공중 내리찍기를 날린다. 꼬리의 불꽃도 무기의 하나이다.', 'The deeper the blue on its face, the more powerful it will grow to become. It leaps about every which way and lands powerful blows against its opponents with the flame on its tail.'),
  ('hisui', 63, 392, true, '스피드로 상대를 농락한다. 양팔 양다리를 활용한 독특한 방식으로 싸운다.', 'A tall, hardy Pokémon with a dazzling appearance. It shrouds itself in flame and battles as if engaged in dance—truly a sight to behold.'),
  ('hisui', 64, 427, true, '말고 있던 귀를 뻗는 힘으로 공격하는 기술은 트레이닝을 할수록 위력이 커진다.', 'My hypothesis as to why Buneary rolls up its ears is that its hearing is far too keen. I surmise that the Pokémon protects its hearing by limiting the sound that may enter its ears.'),
  ('hisui', 65, 428, true, '더운 계절이 끝나면 공기를 많이 머금은 털로 털갈이를 하여 추위에 대비한다.', 'Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.'),
  ('hisui', 65, 10190, false, '더운 계절이 끝나면 공기를 많이 머금은 털로 털갈이를 하여 추위에 대비한다.', 'Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.'),
  ('hisui', 66, 420, true, '몸이 빨간 체리버일수록 영양이 많고 구슬의 맛도 달고 맛있다.', 'Once the fruit growing alongside the main body is large and plump, Cherubi will use the nutrients within to evolve. The fruit then detaches, becoming nourishment for other creatures.'),
  ('hisui', 67, 421, true, '겹쳐진 꽃잎은 딱딱하다. 새포켓몬에게 쪼여도 아무렇지도 않다.', 'Motionless, save for the occasional quiver. A rich array of Pokémon can be found gathered around it, drawn by the scent exuded from Cherrim''s folded petals.'),
  ('hisui', 67, 10038, false, '겹쳐진 꽃잎은 딱딱하다. 새포켓몬에게 쪼여도 아무렇지도 않다.', 'Motionless, save for the occasional quiver. A rich array of Pokémon can be found gathered around it, drawn by the scent exuded from Cherrim''s folded petals.'),
  ('hisui', 68, 54, true, '스트레스가 쌓이면 두통이 심해진다. 강력한 염동력으로 주위를 압도한다.', 'Suffers perpetual headaches. If the agony grows too great, Psyduck''s latent power erupts, contrary to Psyduck''s intent. Ergo, I am exploring ways to ease the pain.'),
  ('hisui', 69, 55, true, '강을 더럽힌 사람을 물속으로 끌어들여 데려간다는 옛날이야기가 전해져 오고 있다.', 'Its body is strong, and it has webbing on its hands and feet. Golduck can swim easily through rough seas, clawing its way through the high waves.'),
  ('hisui', 70, 415, true, '새벽부터 저녁때까지 꿀을 계속 모은다. 모든 것은 무리와 비퀸을 위해서다.', 'They swear fealty to a queen Pokémon and work diligently to gather nectar. Each swarm produces a different flavor of honey.'),
  ('hisui', 71, 416, true, '페로몬을 발산하는 양이 많은 비퀸일수록 많은 세꿀버리를 거느리고 있다.', 'Commands its subjects to build its hive. It will dispatch any interlopers who dare sneak into its nest and use them as nourishment for itself.'),
  ('hisui', 72, 123, true, '숲속에서 많은 나무가 베인 채 쓰러져 있는 장소를 발견했다면 그곳은 스라크의 영역이다.', 'The large, wickedly sharp scythes on its forearms are truly fearsome weapons. Prey''s attempts to flee are unfailingly thwarted by this Pokémon''s nimble motions.'),
  ('hisui', 73, 900, true, null, 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.'),
  ('hisui', 74, 212, true, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'Evolved by way of a curious item. The shell covering its body has been shown to be stronger than forged steel.'),
  ('hisui', 74, 10146, false, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'Evolved by way of a curious item. The shell covering its body has been shown to be stronger than forged steel.'),
  ('hisui', 75, 214, true, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'This Pokémon has an unparalleled horn. Heracross itself demonstrates tremendous power—it''s capable of throwing several people trained in the traditional arts of war at once.'),
  ('hisui', 75, 10147, false, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'This Pokémon has an unparalleled horn. Heracross itself demonstrates tremendous power—it''s capable of throwing several people trained in the traditional arts of war at once.'),
  ('hisui', 76, 439, true, '춤을 잘 추는 마임꽁꽁의 제자인 것마냥 따라다니며 스텝을 열심히 흉내 낸다.', 'Known to turn up in bustling marketplaces now and again. It mimics people much as a child would, then watches how they react, eyes sparkling.'),
  ('hisui', 77, 122, true, '팬터마임이 특기다. 손가락에서 내보내는 파동으로 벽을 만들어 갖은 공격으로부터 몸을 지킨다.', 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
  ('hisui', 77, 10327, false, '팬터마임이 특기다. 손가락에서 내보내는 파동으로 벽을 만들어 갖은 공격으로부터 몸을 지킨다.', 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
  ('hisui', 78, 190, true, '나무 위에서 먹이를 찾는다. 좋아하는 달콤아를 발견하면 흥분해서 덤벼든다.', 'This treetop dweller possesses a tail as dexterous as a hand. Ancient writings describe this Pokémon as a one-armed oddity.'),
  ('hisui', 79, 424, true, '무엇을 하더라도 꼬리를 사용한다. 2개의 꼬리로 껴안는다면 정말로 친밀해졌다는 증거다.', 'To affirm their kinship, members of this species will form a ring by linking their newly doubled tails together. On rare occasions, humans have been accepted into such rings.'),
  ('hisui', 80, 129, true, '유속이 빠른 곳에서는 그저 떠내려갈 뿐인 약하고 한심한 포켓몬이다.', 'A feeble, pitiful imbecile of a Pokémon that is nonetheless very hardy. Unperturbed by turbid water, it can be found living in all sorts of places.'),
  ('hisui', 81, 130, true, '한번 난동부리기 시작한 갸라도스는 태풍이 사납게 휘몰아쳐도 모든 것을 다 태워버린다.', 'I suspect this Pokémon to be the true identity of a dragon written of in ancient texts, which claimed that it razed an entire village with white-hot beams from its maw.'),
  ('hisui', 81, 10141, false, '한번 난동부리기 시작한 갸라도스는 태풍이 사납게 휘몰아쳐도 모든 것을 다 태워버린다.', 'I suspect this Pokémon to be the true identity of a dragon written of in ancient texts, which claimed that it razed an entire village with white-hot beams from its maw.'),
  ('hisui', 82, 422, true, '세게 만지면 보라색의 정체 모를 액체를 내보낸다. 해롭지는 않지만 끈적거린다.', 'Found in abundance on seashores bordering warm waters. Shellos are unexpectedly friendly and will crawl toward any person they see. Take care not to get coated in mucus!'),
  ('hisui', 82, 10039, false, '세게 만지면 보라색의 정체 모를 액체를 내보낸다. 해롭지는 않지만 끈적거린다.', 'Found in abundance on seashores bordering warm waters. Shellos are unexpectedly friendly and will crawl toward any person they see. Take care not to get coated in mucus!'),
  ('hisui', 83, 423, true, '흐물흐물한 몸이지만 제법 튼튼하다. 부드러워서 충격을 분산시킨다.', 'Eats beach sand for nourishment. Should one Gastrodon encounter another of a different color, a fierce battle will inevitably ensue.'),
  ('hisui', 83, 10040, false, '흐물흐물한 몸이지만 제법 튼튼하다. 부드러워서 충격을 분산시킨다.', 'Eats beach sand for nourishment. Should one Gastrodon encounter another of a different color, a fierce battle will inevitably ensue.'),
  ('hisui', 84, 211, true, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('hisui', 84, 10403, false, '전신의 작은 바늘은 비늘이 변화한 것이다. 찔리면 독 때문에 정신을 잃게 된다.', 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
  ('hisui', 85, 904, true, null, 'Its lancelike spikes and savage temperament have earned it the nickname ”sea fiend.” It slurps up poison to nourish itself.'),
  ('hisui', 86, 440, true, '친해진 상대에게는 소중하게 여기는 둥근 돌을 빌려준다. 돌려주지 않으면 울고불고하다가 난폭해진다.', 'In imitation of Chansey, it keeps a round stone tucked into its belly pouch and cherishes it dearly. It gets along well with children and will sometimes play house with them for fun.'),
  ('hisui', 87, 113, true, '원래 움직임이 둔했지만 알을 노리는 자들로부터 지켜내기 위해 도주 속도가 빨라졌다.', 'This purehearted Pokémon shares its eggs with the injured.'),
  ('hisui', 88, 242, true, '행복이 가득 찬 신비한 알을 낳는다. 먹은 사람은 누구에게나 친절해진다고 한다.', 'A kindhearted Pokémon that will care for any sick person or Pokémon until their health improves. The eggs it lays are delicious and bring good fortune to those who eat them.'),
  ('hisui', 89, 406, true, '기온 변화에 민감하다. 봉오리가 피기 시작하면 곧 봄이 온다.', 'When the sun''s light strengthens, the bud atop this Pokémon''s head opens. This is a sign to the people that the harsh winter is over, and the season of budding has begun.'),
  ('hisui', 90, 315, true, '오른손과 왼손으로 2종류의 독을 구별하여 공격한다. 향기가 강할수록 기운이 넘친다.', 'Though beautiful, it has highly poisonous thorns. There is an old tradition in my homeland wherein one would send these thorns to an opponent to challenge them to a duel.'),
  ('hisui', 91, 407, true, '오른손의 독은 즉효성이고 왼손의 독은 지효성을 띠고 있다. 양쪽 모두 생명에 지장을 준다.', 'Hidden within the bouquet on each hand are thorned whips loaded with virulent poison. Roserade moves gracefully as it corners its prey and mercilessly lashes them with its whips.'),
  ('hisui', 92, 455, true, '늪지대에서 자라는 나무에 엉겨 붙어 달콤한 냄새의 타액으로 먹이를 끌어들여 한입에 먹는다.', 'Though this is a plant Pokémon, it has a gluttonous and unruly temperament. Carnivine attacks its prey with its cavernous maw wide open.'),
  ('hisui', 93, 548, true, '잎사귀의 색이 짙을수록 건강하다. 잘 정돈된 밭이나 화단에 자리잡고 살기도 한다.', 'The leaves on its head are highly valued for medicinal purposes. Dry the leaves in the sun, boil them, and then drink the bitter decoction for remarkably effective relief from fatigue.'),
  ('hisui', 94, 549, true, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('hisui', 94, 10406, false, '꽃으로 만든 정유는 최고의 향을 내지만 눈이 튀어나올 정도로 비싸다.', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
  ('hisui', 95, 114, true, '덩굴은 독특한 향이 난다. 가라르 일부 지역에서는 허브로 사용되고 있다.', 'It is cloaked entirely in blue vines, preventing any glimpse of its true identity. The vines impart a refreshing sensation when chewed—they''re useful as a spice.'),
  ('hisui', 96, 465, true, '따듯한 땅에서 살수록 덩굴의 성장이 빠르다. 길어지면 스스로 잘라내어 짧게 만든다.', 'Draped with long vines, it resembles a shrub in appearance. It swings bundles of vines as though they were arms, wrapping them around prey to ensnare them.'),
  ('hisui', 97, 339, true, '2개의 긴 수염으로 탁한 강바닥을 더듬는다. 미끈미끈한 점막으로 몸을 보호한다.', 'Makes its home in swamps with murky water. The poor visibility hides this Pokémon from predators, and the slime on its body makes grasping it difficult.'),
  ('hisui', 98, 340, true, '큰 늪을 영역으로 한다. 적이 가까이 오면 크게 난동부려서 큰 지진을 일으킨다.', 'Strikes its caudal fin against the swamp bed to shake the ground and startle its prey. It will then swallow the fleeing prey whole. People mistook this behavior as the cause of earthquakes.'),
  ('hisui', 99, 453, true, '독을 희석하면 약이 된다. 제약 회사의 마스코트가 된 후로 인기가 많아졌다.', 'A poison wielder with a dastardly personality. Despite such qualities, this species is afforded a measure of popularity due to its peculiar cry and comical features.'),
  ('hisui', 100, 454, true, '사냥감을 처리하면 개굴개굴하며 승리를 자축하는 소리를 높인다. 두빅굴과 가까운 종이다.', 'Its crimson claws contain a virulent toxin. This toxin can be made into a tonic by diluting it, mixing it with several types of wild grass, and boiling it down over two days.'),
  ('hisui', 101, 280, true, '빨간 뿔로 사람이나 포켓몬의 따뜻한 마음을 캐치하면 전신이 미약하게 뜨거워진다.', 'Tends to prefer people with a chipper disposition to those who are gloomy, but it has shown no discrimination with regard to age or gender. Needs more research.'),
  ('hisui', 102, 281, true, '사이코 파워를 조작해 주변의 공간을 일그러뜨려 미래를 내다볼 수 있다.', 'It resembles a maiden in appearance, but it wields strange powers to project visions of paradise. I suspect the crimson ornaments on its head are the key to its abilities.'),
  ('hisui', 103, 282, true, '트레이너를 지키기 위해서라면 사이코 파워를 모두 써서 작은 블랙홀을 만들어 낸다.', 'It will dedicate itself to defending a master it has come to adore. Its pure white dress, reminiscent of those worn by ladies of nobility, is the dress of one who is willing to risk their life.'),
  ('hisui', 103, 10151, false, '트레이너를 지키기 위해서라면 사이코 파워를 모두 써서 작은 블랙홀을 만들어 낸다.', 'It will dedicate itself to defending a master it has come to adore. Its pure white dress, reminiscent of those worn by ladies of nobility, is the dress of one who is willing to risk their life.'),
  ('hisui', 104, 475, true, '도움을 구하는 감정을 민감하게 캐치해서 상대가 있는 곳으로 급히 달려가 가세한다.', 'The blades extending from its elbows are sharper than the finest swords. Its swordsmanship, albeit self-taught, is astonishingly impressive.'),
  ('hisui', 104, 10170, false, '도움을 구하는 감정을 민감하게 캐치해서 상대가 있는 곳으로 급히 달려가 가세한다.', 'The blades extending from its elbows are sharper than the finest swords. Its swordsmanship, albeit self-taught, is astonishingly impressive.'),
  ('hisui', 105, 193, true, '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', 'Its frail wings are so thin that one can see clear through them. However, during flight these wings exhibit the power to churn air with force enough to launch a house skyward.'),
  ('hisui', 106, 469, true, '6개의 다리로 어른을 껴안고도 너끈히 날 수 있다. 꼬리의 날개로 균형을 잡는다.', 'Extremely violent. When hunting, it wastes none of its energy, aiming only for prey''s most vulnerable spots. Any who manage to tame this Pokémon must be of incredible bravery.'),
  ('hisui', 107, 449, true, '주로 낮에 활동한다. 사막의 밤은 기온이 낮아져 모래 깊숙이 들어가 잠을 잔다.', 'Though large and languid, Hippopotas is difficult to detect due to its tendency to burrow into and lurk beneath the soil. When agitated or excited, it expels sand from its nostrils.'),
  ('hisui', 108, 450, true, '화나게 하면 굉장히 흉포해진다. 들이마신 모래를 내뿜어 모래바람을 일으킨다.', 'Short-tempered and easily moved to violence. It whips up whirlwinds of sand to crush its foes'' spirits, then goes in for the attack.'),
  ('hisui', 109, 417, true, '모인 전기를 나눠주려고 뺨의 주머니를 서로 비비는 파치리스가 발견되기도 한다.', 'A species related to the Pikachu line. Though Pachirisu is a calm Pokémon, it still presents a danger should one touch its electrified tail or cheeks.'),
  ('hisui', 110, 434, true, '꼬리를 들고 엉덩이를 돌리면 주의해야 한다. 기절할 정도로 악취 나는 분비액을 날릴 전조인 것이다.', 'The poison that gushes from its aft end is accompanied by an utterly evil-smelling odor with such potency that one whiff can induce memory loss.'),
  ('hisui', 111, 435, true, '꼬리 끝에서 날리는 분비액의 냄새는 강렬하다. 땅에 구멍을 파서 굴을 만든다.', 'Sprays a poisonous fluid to take down prey. Sometimes, unable to stomach the stench of its own fluid, it leaves the bested prey uneaten.'),
  ('hisui', 112, 216, true, '꿀이 밴 손바닥을 핥고 있다. 깜지곰의 꿀은 과일과 독침붕이 모은 꽃가루가 혼합되어 만들어진다.', 'It licks its paws because of the sweet honey that has soaked into them. It is cunning, stealing into the nests of Combee and taking for itself the honey that the Combee have amassed.'),
  ('hisui', 113, 217, true, '숲 속에는 링곰이 먹이를 수집하는 큰 나무나 시냇가가 여기저기에 있다고 한다. 매일 먹이를 모으며 숲을 걷는다.', 'When the cold season arrives in Hisui, this Pokémon will wander fields and mountains alike in search of its favorite berries. Ursaring''s hunger during this time makes it a ferocious danger.'),
  ('hisui', 114, 901, true, null, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.'),
  ('hisui', 115, 704, true, '뿔은 뛰어난 감각 기관이다. 적의 기척을 느끼면 바로 숨어들어 살아남아 왔다.', 'Goomy hides away in the shade of trees, where it''s nice and humid. If the slime coating its body dries out, the Pokémon instantly becomes lethargic.'),
  ('hisui', 116, 705, true, '등의 돌기 안에 작은 뇌가 있다. 먹이에 대한 생각과 적으로부터 도망치는 생각만 한다.', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
  ('hisui', 116, 10410, false, '등의 돌기 안에 작은 뇌가 있다. 먹이에 대한 생각과 적으로부터 도망치는 생각만 한다.', 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
  ('hisui', 117, 706, true, '긴 뿔을 기세 좋게 늘여서 공격한다. 위력은 헤비급 복서 펀치의 100배다.', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
  ('hisui', 117, 10411, false, '긴 뿔을 기세 좋게 늘여서 공격한다. 위력은 헤비급 복서 펀치의 100배다.', 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
  ('hisui', 118, 95, true, '크고 튼튼한 몸을 뒤틀고 꼬아서 시속 80km로 힘차게 땅을 파나간다.', 'This chain of immense stones resembles a giant serpent. Tremors shake the earth above as it burrows deep beneath the ground, feeding on boulders as it goes.'),
  ('hisui', 119, 208, true, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
  ('hisui', 119, 10174, false, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
  ('hisui', 120, 111, true, '한 가지만 기억할 수 있다. 돌진하기 시작하면 이유가 무엇이었든 금방 잊어버린다.', 'Ludicrously strong—when it butts heads with a mountain, it is the mountain that shatters. But its short legs struggle with turns, and it is incapable of stopping unless it collides with something.'),
  ('hisui', 121, 112, true, '전신을 갑옷 같은 피부로 보호하고 있다. 2000도의 마그마 속에서도 살 수 있다.', 'Rapidly rotates its horn to bore through bedrock. It swaggers around volcanic regions, protected from the lava''s heat by its tough, armorlike hide.'),
  ('hisui', 122, 464, true, '프로텍터로 공격을 튕겨내고 상대가 풀이 죽으면 특징적인 드릴로 관통한다.', 'This Pokémon evolved through use of a curious item. Its rocklike hide is composed of a mysterious substance and can withstand a blow from a masterwork sword with nary a scratch.'),
  ('hisui', 123, 438, true, '건조한 바위 밭에 산다. 초록색 구슬은 마를수록 반들반들 희미하게 빛난다.', 'Its tears elicit sympathy from those who see them, but do not be deceived! This expulsion of body water is merely a physiological mechanism for keeping itself in good health.'),
  ('hisui', 124, 185, true, '습격당하지 않도록 나무 흉내를 낸다. 물에 약하기 때문에 비가 내리면 어느 틈에 모습을 감춰버린다.', 'Though it pretends to be a tree, it fails to fool even children. To the touch, its body feels more like rock than tree bark. Sudowoodo''s extreme aversion to water merits special note.'),
  ('hisui', 125, 108, true, '벌레포켓몬이 주된 먹이다. 긴 혀로 상대를 핥아 마비시킨 후 통째로 삼킨다.', 'Wields its long tongue deftly, as though it were an arm. The Pokémon''s viscous saliva, once it has been collected and boiled down, yields a strong and highly useful adhesive.'),
  ('hisui', 126, 463, true, '사람의 팔과 견줄 수 있을 정도의 활용도 높은 혀로 뭐든지 한다. 반대로 손은 무디다.', 'Its tongue can extend and contract freely, and it is capable of reaching lengths over 10 times Lickilicky''s height. Beware of the saliva, as it contains corrosive elements.'),
  ('hisui', 127, 175, true, '행운의 상징이다. 껍질 안에는 행복이 가득 담겨 있다고 한다.', 'This ovate creature is frequently mistaken for a moving egg when encountered out in the fields or in the mountains. Its guileless smile soothes the soul.'),
  ('hisui', 128, 176, true, '상냥한 사람 곁에 있지 않으면 기운을 내지 못한다. 날개를 움직이지 않고도 공중에 뜰 수 있다.', 'No records exist of Togetic being seen in the wilds. Rumors abound that it evolves under the loving care of a trusted human companion, upon whom the Pokémon then bestows great joy.'),
  ('hisui', 129, 468, true, '은총을 베푸는 존재로 전해지고 있으며 먼 옛날부터 길조로 묘사되어 왔다.', 'Scant few have ever sighted this Pokémon. After studying what literature remains, I am certain Togekiss will reveal itself when peace reigns in the land.'),
  ('hisui', 130, 387, true, '전신으로 광합성을 하여 산소를 만든다. 목이 마르면 머리의 잎사귀가 시들어 버린다.', 'This Pokémon becomes more energetic the more sunlight there is. The part resembling a shell is similar to silt and is slightly damp and warm to the touch.'),
  ('hisui', 131, 388, true, '깨끗한 물이 솟아나는 장소를 알고 있어서 동료 포켓몬을 등에 태우고 그곳까지 데려다 준다.', 'Appears where there is clean spring water. The fruit that grows on the shrubs on its shell is sweet, nutritious, and truly delicious.'),
  ('hisui', 132, 389, true, '작은 포켓몬들이 모여 움직이지 않는 토대부기의 등에서 둥지를 만들려고 하는 경우가 있다.', 'This remarkable, large-bodied Pokémon would serve beautifully as borrowed scenery for a garden, and its strength is peerless. Torterra roams the wilderness in search of clean water.'),
  ('hisui', 133, 137, true, '근래에는 컴퓨터 공간에서 대활약한다. 수상한 데이터가 없는지 체크하며 돌아다닌다.', 'It has no discernible heartbeat and does not seem to draw breath, and yet it appears to function without issue. I cannot even begin to explain this utterly bizarre anomaly.'),
  ('hisui', 134, 233, true, 'AI 기능을 탑재한 결과 폴리곤2끼리만 통하는 수수께끼의 언어로 말하기 시작했다.', 'A bizarre item caused this Pokémon to evolve. While it now exhibits many new gestures and expressions, its biology remains inscrutable.'),
  ('hisui', 135, 474, true, '추가 프로그램으로 진화했다고 전해지지만 정말 진화인 건지 학회에서도 의견이 나뉜다.', 'A curious item induced this evolution. The Pokémon''s offensive capabilities have greatly increased, but the strangeness of its behavior has magnified in equal measure. This worries me.'),
  ('hisui', 136, 92, true, '몸은 옅은 가스로 되어 있어 어디든지 숨어들어 가지만 바람이 불면 날아가 버린다.', 'Gaseous and completely impalpable. Also highly dangerous— inhaling part of its poisonous body will cause one to faint instantly.'),
  ('hisui', 137, 93, true, '어둠 속에서 아무도 없는데도 누군가가 보고 있다는 느낌이 들면 그곳에 고우스트가 있는 것이다.', 'This frightful, malevolent spirit can glide through walls, appearing wherever it likes. According to rumor, victims of a Haunter''s lick will wither to death day by day.'),
  ('hisui', 138, 94, true, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('hisui', 138, 10138, false, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('hisui', 138, 10371, false, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('hisui', 139, 442, true, '나쁜 짓만 일삼다가 신비한 술수를 사용하는 여행자에 의해 쐐기돌에 속박당했다.', 'It lays curses by thinking wicked thoughts. Writings tell that this Pokémon was born out of the assembly of five score and eight malevolent spirits.'),
  ('hisui', 140, 198, true, '보스를 위해 반짝반짝 빛나는 것을 찾고 있다. 불길한 존재로 여겨 몹시 싫어하는 사람도 많다.', 'Widely shunned as a bearer of ill fortune. Upon crossing paths with this creature, I''ve been told one must chant ”Workrum, Workrum—bad luck, don''t come” as a protective incantation.'),
  ('hisui', 141, 430, true, '적과 싸우는 것은 거의 부하다. 자신의 손을 더럽히는 것은 상대에게 마지막 일격을 가할 때뿐이다.', 'One cry from this Pokémon, and a murder of Murkrow come flying. At such times, one would think the curtain of night had fallen, plunging the world into jet-black darkness.'),
  ('hisui', 142, 201, true, '고대 문자를 닮은 모습의 포켓몬이다. 먼저 생겨난 것은 문자인가 안농인가. 연구 중이지만 아직도 수수께끼다.', 'It is hard to believe these strangely shaped Pokémon are truly living creatures. I''ve pointed out that the species'' many forms resemble writing from other lands; no one will take me seriously.'),
  ('hisui', 142, 10001, false, '고대 문자를 닮은 모습의 포켓몬이다. 먼저 생겨난 것은 문자인가 안농인가. 연구 중이지만 아직도 수수께끼다.', 'It is hard to believe these strangely shaped Pokémon are truly living creatures. I''ve pointed out that the species'' many forms resemble writing from other lands; no one will take me seriously.'),
